/**
 * Every researched outcome-web link either reaches an engine's own records
 * or is listed in src/core2/data/outcome-web/unwired.json with its exact
 * reason and an open stopgap that carries it. The list is regenerated by
 * scripts/outcome-web/write-unwired.ts; this fails when it and the effect
 * matrix disagree, so no link goes quiet.
 */
import { describe, expect, it } from "vitest";
import data from "./data/outcome-web/unwired.json" with { type: "json" };
import stopgaps from "./data/stopgaps.json" with { type: "json" };
import { unwiredRows } from "../../scripts/outcome-web/write-unwired";

describe("the outcome web's unwired links", () => {
  it("match the effect matrix, each with its reason", () => {
    expect(data.links).toEqual(unwiredRows());
    for (const row of data.links) expect(row.reason.length).toBeGreaterThan(20);
  });

  it("each name an open stopgap row", () => {
    const open = new Set(
      (stopgaps as { id: string; status?: string }[])
        .filter((row) => row.status === "open")
        .map((row) => row.id),
    );
    for (const row of data.links)
      expect(open.has(row.stopgapId), `${row.link} ${row.stopgapId}`).toBe(
        true,
      );
  });
});
